import{_ as r,C as l,c as i,o as h,a3 as n,j as e,G as o,a as s}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Sub-tasks","description":"","frontmatter":{},"headers":[],"relativePath":"master/services/project/task-management/sub-tasks.md","filePath":"master/services/project/task-management/sub-tasks.md","lastUpdated":1793074831000}'),p={name:"master/services/project/task-management/sub-tasks.md"};function d(g,t,m,u,k,c){const a=l("ImagePopup");return h(),i("div",null,[t[4]||(t[4]=n('<h1 id="sub-tasks" tabindex="-1">Sub-tasks <a class="header-anchor" href="#sub-tasks" aria-label="Permalink to &quot;Sub-tasks&quot;">​</a></h1><p>A sub-task is a smaller task that belongs to a parent task. Use it when one task has several parts, or when different people do different parts. Sub-tasks do not show in the main task list. You reach them from the parent.</p><blockquote><p><strong>In simple words:</strong> A sub-task is a task inside a task. Its hours add up on the parent.</p></blockquote><p>Open the parent task and click <strong>Sub Tasks</strong> in the links at the top of the page.</p><div class="warning custom-block"><p class="custom-block-title">Prerequisite</p><p>The parent task must exist and its project needs task stages. See <a href="./task-stages-and-states.html">Task stages and states</a>.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The time totals need <strong>Enable Timesheets</strong>. See <a href="./../../timesheets/timesheet-settings.html">Timesheet settings</a>.</p></div><h2 id="create-a-sub-task" tabindex="-1">Create a sub-task <a class="header-anchor" href="#create-a-sub-task" aria-label="Permalink to &quot;Create a sub-task&quot;">​</a></h2><p>The example adds <strong>Draft email copy</strong> under <strong>Prepare launch announcement</strong>.</p>',8)),e("ol",null,[e("li",null,[t[0]||(t[0]=e("p",null,[s("Open "),e("code",null,"Project → Tasks"),s(", click "),e("strong",null,"Prepare launch announcement"),s(", then click "),e("strong",null,"Sub Tasks"),s(".")],-1)),o(a,{src:"/images1/project/tk_sub_tasks_tab.png",alt:"Sub Tasks tab of the parent task with the Add Sub Task button"})]),e("li",null,[t[1]||(t[1]=e("p",null,[s("Click "),e("strong",null,"Add Sub Task"),s(". A large form opens with the same fields as a task.")],-1)),o(a,{src:"/images1/project/tk_sub_task_modal.png",alt:"Add Sub Task form with values copied from the parent task"})]),e("li",null,[t[2]||(t[2]=n("<p>The form opens with values copied from the parent. Type <strong>Draft email copy</strong> in <strong>Title</strong>. Set <strong>Allocated Hours</strong> to 6. Change any copied value if needed.</p><ul><li><strong><em>Stage:</em></strong> The first stage of the project, <strong>New</strong>.</li><li><strong><em>State:</em></strong> <strong>In Progress</strong>.</li><li><strong><em>Project:</em></strong>, <strong><em>Milestone:</em></strong>, <strong><em>Customer:</em></strong> and <strong><em>Assignees:</em></strong> The same as the parent.</li></ul>",2)),o(a,{src:"/images1/project/tk_sub_task_filled.png",alt:"Sub task form filled with title Draft email copy and allocated hours 6"})]),e("li",null,[t[3]||(t[3]=e("p",null,[s("Click "),e("strong",null,"Create"),s(". The sub-task appears in the table. Check "),e("code",null,"Project → Tasks"),s(": the sub-task is not in the main list. Only the parent shows.")],-1)),o(a,{src:"/images1/project/tk_sub_task_created.png",alt:"Sub Tasks tab listing Draft email copy"})])]),t[5]||(t[5]=n('<p>The table has the same columns as the task list and a <strong>Trashed</strong> filter. Use the row menu for <strong>Delete</strong>, <strong>Restore</strong> and <strong>Force delete</strong>.</p><h2 id="how-time-rolls-up" tabindex="-1">How time rolls up <a class="header-anchor" href="#how-time-rolls-up" aria-label="Permalink to &quot;How time rolls up&quot;">​</a></h2><p>Log time on the sub-task like on any task. On the parent, scroll down the <strong>View</strong> page. The <strong>Timesheets</strong> tab then shows these totals.</p><table tabindex="0"><thead><tr><th>Total</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Time Spent</strong></td><td>Hours logged on the parent itself</td></tr><tr><td><strong>Time Spent on Subtasks</strong></td><td>Hours logged on all its sub-tasks</td></tr><tr><td><strong>Total Time Spent</strong></td><td>The two added together</td></tr><tr><td><strong>Remaining Time</strong></td><td>Allocated hours minus the total</td></tr></tbody></table><p><strong>Migrate CMS content</strong> has 20 allocated hours. People logged 13 hours on it. Its two sub-tasks, <strong>Export legacy articles</strong> and <strong>Import and re-format media</strong>, hold 6 hours each. Those 12 hours count toward the parent. The totals are 13 hours, 12 hours, 25 hours and minus 5 hours remaining.</p>',5)),o(a,{src:"/images1/project/tk_parent_timesheets_totals.png",alt:"Timesheets tab of Migrate CMS content with Time Spent 13, Time Spent on Subtasks 12, Total Time Spent 25 and Remaining Time minus 5"}),t[6]||(t[6]=n('<p>The <strong>Statistics</strong> block on the parent view page shows how many sub-tasks it has.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Give the sub-tasks their own assignees and deadlines. Each person then finds their part under <strong>My Tasks</strong>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./create-task.html">Create a task</a></li><li><a href="./task-list-views-and-filters.html">Task list views and filters</a></li><li><a href="./../../timesheets/log-time.html">Log time</a></li><li><a href="./../../timesheets/">Timesheets overview</a></li></ul>',4))])}const _=r(p,[["render",d]]);export{b as __pageData,_ as default};
